'use strict';
// A self-contained prototype: edits and publication snapshots stay in this browser.
const Builder=(()=>{
const types={hero:{name:'Hero',icon:'layout',hint:'A clear introduction',title:'Leadership without limits.',body:'Discover how inclusion moves business forward.',button:'Explore our mission'},highlights:{name:'Highlights',icon:'layers',hint:'Three reasons to engage',title:'Ideas. Community. Impact.',body:'Research that informs|Connections that matter|Initiatives that move us'},quote:{name:'Quote',icon:'heart',hint:'A voice from your team',title:'Equality belongs at the heart of business.',body:'Illustrative editorial quote',button:'Out Leadership'},cta:{name:'Call to action',icon:'arrow',hint:'A simple next step',title:'Make room for what comes next.',body:'Explore the possibilities with Out Leadership.',button:'Get involved'}};
const themes={coral:{accent:'#c7472d',soft:'#ffebe5',name:'Coral'},lilac:{accent:'#6550c3',soft:'#ece8fb',name:'Lilac'},mint:{accent:'#277057',soft:'#e1f3ec',name:'Mint'}};
const clone=x=>JSON.parse(JSON.stringify(x));const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let seq=3,model={theme:'coral',layout:'split',blocks:[{id:'b1',type:'hero',title:types.hero.title,body:types.hero.body,button:types.hero.button},{id:'b2',type:'highlights',title:types.highlights.title,body:types.highlights.body,button:''}]},selected='b1',device='desktop',history=[],published=null,version=0,dirty=true;
try{const stored=JSON.parse(localStorage.getItem('ol-builder-v1'));if(stored&&themes[stored.theme]&&['split','center'].includes(stored.layout)&&Array.isArray(stored.blocks)&&stored.blocks.length<=8&&stored.blocks.every(b=>types[b.type]&&['title','body','button','id'].every(k=>typeof b[k]==='string'&&b[k].length<=600))&&new Set(stored.blocks.map(b=>b.id)).size===stored.blocks.length){model=stored;selected=model.blocks[0]?.id;seq=Date.now()}}catch{}
function markup(){return '<div class="builder" id="builder"><div class="builder-intro"><span>'+icon('layers')+' YOUR PAGE, YOUR WAY</span><p>1. Add a block　 2. Make it yours　 3. Preview &amp; publish</p></div><div class="builder-toolbar"><div><span id="builder-state" class="builder-state">Draft</span><span id="builder-save" class="builder-save">Changes stay in this browser</span></div><div class="builder-actions"><button id="builder-undo">'+icon('left')+' Undo</button><button id="builder-reset">Reset example</button><button id="builder-publish" class="builder-primary">'+icon('rocket')+' Publish preview</button></div></div><div class="builder-workspace"><aside class="builder-sidebar"><h4>Add a building block</h4><p>Approved components. No code.</p><div class="block-library">'+Object.entries(types).map(([key,t])=>'<button data-add="'+key+'">'+icon(t.icon)+'<span><strong>'+t.name+'</strong><small>'+t.hint+'</small></span>'+icon('plus')+'</button>').join('')+'</div><div class="builder-list-heading"><h4>Your page</h4><span id="block-count"></span></div><div id="block-list"></div><div class="builder-brand"><h4>Brand palette</h4><div class="builder-themes">'+Object.entries(themes).map(([key,t])=>'<button data-builder-theme="'+key+'" aria-label="'+t.name+' brand palette" aria-pressed="false" style="background:'+t.accent+'"></button>').join('')+'</div><p>Change the palette. Keep the identity.</p></div></aside><div class="builder-canvas-zone"><div class="builder-canvas-toolbar"><span>'+icon('globe')+' LIVE PREVIEW</span><div><button data-device="desktop" aria-label="Desktop preview" aria-pressed="true">'+icon('layout')+'</button><button data-device="mobile" aria-label="Mobile preview" aria-pressed="false">'+icon('devices')+'</button></div></div><div class="builder-canvas-scroll"><div id="builder-canvas" class="builder-canvas"></div></div><p class="builder-canvas-hint">'+icon('pointer')+' Select a section in the preview to edit it.</p></div><aside class="builder-inspector"><div id="builder-inspector"></div><div class="builder-reassurance">'+icon('shield')+'<p><strong>Creative freedom. Brand guardrails.</strong> Layout, spacing and responsive behavior are handled by the components.</p></div></aside></div><div id="builder-status" class="builder-status" role="status" aria-live="polite">Start with the hero: change its title and watch the page update.</div><dialog id="builder-dialog" class="builder-dialog" aria-labelledby="builder-dialog-title"><div class="builder-dialog-header"><div><span class="tag">SIMULATED PUBLICATION</span><h3 id="builder-dialog-title">Your page is ready to preview.</h3><p id="builder-dialog-description"></p></div><button id="builder-close" aria-label="Close published preview">'+icon('plus')+'</button></div><div id="builder-published" class="builder-published"></div><div class="builder-dialog-footer"><span>No external website is changed. This is a browser-only preview.</span><button id="builder-export" class="builder-primary">'+icon('file')+' Download your page</button></div></dialog></div>'}
function save(){try{localStorage.setItem('ol-builder-v1',JSON.stringify(model));document.querySelector('#builder-save').textContent='Draft saved on this device'}catch{document.querySelector('#builder-save').textContent='Draft kept for this session'}}
function checkpoint(){history.push({model:clone(model),selected});if(history.length>30)history.shift()}
function announce(t){document.querySelector('#builder-status').textContent=t}
function touch(){dirty=true;save();document.querySelector('#builder-state').textContent=published?'Unpublished changes':'Draft';document.querySelector('#builder-state').classList.remove('is-published');document.querySelector('#builder-undo').disabled=!history.length}
function styles(){return '.page-preview{--page-accent:#c7472d;--page-soft:#ffebe5;background:white;color:#17243c;font-family:Arial,Helvetica,sans-serif;line-height:1.5}.page-preview *{box-sizing:border-box}.page-preview h1,.page-preview h2,.page-preview p{margin:0}.page-preview h1,.page-preview h2{letter-spacing:-1px;line-height:1.13;color:#17243c}.page-preview .page-nav{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;font-size:9px;border-bottom:1px solid #e2e7f0}.page-preview .page-nav strong{font-size:11px}.page-preview .page-section{padding:28px 22px;position:relative;overflow-wrap:anywhere}.page-preview .page-section-label{font-size:8px;letter-spacing:1.4px;display:block;color:var(--page-accent);margin-bottom:10px;font-weight:bold}.page-preview .page-hero{background:var(--page-soft);display:grid;grid-template-columns:1.3fr .7fr;gap:15px;align-items:center}.page-preview .page-hero h1{font-size:32px}.page-preview .page-section p{font-size:11px;color:#627087;line-height:1.7;margin-top:13px;white-space:pre-line}.page-preview .page-action{display:inline-block;background:var(--page-accent);color:white;border:0;font-size:10px;border-radius:6px;padding:10px 14px;margin-top:18px;text-decoration:none}.page-preview .page-art{height:125px;border:23px solid var(--page-accent);border-radius:80px;transform:rotate(-25deg);opacity:.65}.page-preview .page-hero.center{display:block;text-align:center}.page-preview .page-hero.center .page-art{display:none}.page-preview .page-highlights h2{font-size:23px}.page-preview .page-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:17px}.page-preview .page-card{border:1px solid #e2e7f0;border-radius:8px;padding:15px 10px;font-size:10px}.page-preview .page-card span{font-size:18px;display:block;color:var(--page-accent);margin-bottom:10px}.page-preview .page-quote{background:#f6f7fb}.page-preview .page-quote .quote-mark{font-size:50px;line-height:.8;color:var(--page-accent);display:block;margin-bottom:12px}.page-preview .page-quote h2{font-size:25px}.page-preview .page-quote .page-attribution{font-size:10px;color:var(--page-accent);display:block;margin-top:15px}.page-preview .page-cta{text-align:center;background:var(--page-soft)}.page-preview .page-cta h2{font-size:26px}.page-preview .page-footer{font-size:8px;padding:16px 22px;color:#627087;border-top:1px solid #e2e7f0}.page-preview.is-mobile .page-hero{grid-template-columns:1fr}.page-preview.is-mobile .page-art{display:none}.page-preview.is-mobile .page-cards{grid-template-columns:1fr}.page-preview.is-mobile .page-hero h1{font-size:27px}@media(max-width:500px){.page-preview .page-hero{grid-template-columns:1fr}.page-preview .page-art{display:none}.page-preview .page-cards{grid-template-columns:1fr}}'}
function blockHTML(b){const title=escape(b.title),body=escape(b.body),button=escape(b.button);if(b.type==='hero')return '<div class="page-section page-hero '+(model.layout==='center'?'center':'')+'"><div><span class="page-section-label">RETURN ON EQUALITY</span><h1>'+title+'</h1><p>'+body+'</p><span class="page-action">'+button+' ↗</span></div><div class="page-art" aria-hidden="true"></div></div>';if(b.type==='highlights')return '<div class="page-section page-highlights"><span class="page-section-label">EXPLORE THE POSSIBILITIES</span><h2>'+title+'</h2><div class="page-cards">'+b.body.split('|').slice(0,3).map((t,i)=>'<div class="page-card"><span aria-hidden="true">'+['↗','◎','✧'][i]+'</span>'+escape(t)+'</div>').join('')+'</div></div>';if(b.type==='quote')return '<div class="page-section page-quote"><span class="quote-mark" aria-hidden="true">“</span><h2>'+title+'</h2><p>'+body+'</p><span class="page-attribution">'+button+'</span></div>';return '<div class="page-section page-cta"><h2>'+title+'</h2><p>'+body+'</p><span class="page-action">'+button+' ↗</span></div>'}
function pageHTML(editable=false){const t=themes[model.theme];return '<div class="page-preview '+(device==='mobile'&&editable?'is-mobile':'')+'" style="--page-accent:'+t.accent+';--page-soft:'+t.soft+'"><div class="page-nav"><strong>OUT / LEADERSHIP</strong><span>Your page</span></div>'+model.blocks.map(b=>editable?'<div class="builder-section '+(b.id===selected?'selected':'')+'" data-select-block="'+escape(b.id)+'" role="button" tabindex="0" aria-label="Edit '+types[b.type].name+' block"><span class="builder-selection-label">'+escape(types[b.type].name)+'</span>'+blockHTML(b)+'</div>':blockHTML(b)).join('')+(!model.blocks.length?'<div class="builder-empty">Your canvas is ready.<br>Add a building block to start.</div>':'')+'<div class="page-footer">Out Leadership · Illustrative page created in the proposal builder</div></div>'}
function renderCanvas(){const c=document.querySelector('#builder-canvas');c.classList.toggle('mobile',device==='mobile');c.innerHTML='<style>'+styles()+'</style>'+pageHTML(true);c.querySelectorAll('[data-select-block]').forEach(el=>{el.onclick=()=>select(el.dataset.selectBlock);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(el.dataset.selectBlock)}}});const active=[...c.querySelectorAll('[data-select-block]')].find(el=>el.dataset.selectBlock===selected),scroll=document.querySelector('.builder-canvas-scroll');if(active){const rect=active.getBoundingClientRect(),view=scroll.getBoundingClientRect();if(rect.top<view.top||rect.bottom>view.bottom)scroll.scrollTop+=rect.top-view.top-16}}
function select(id){selected=id;renderList();renderInspector();renderCanvas()}
function renderList(){document.querySelector('#block-count').textContent=model.blocks.length+'/8 blocks';document.querySelector('#block-list').innerHTML=model.blocks.map((b,i)=>'<div class="builder-list-item '+(b.id===selected?'active':'')+'"><button data-select="'+escape(b.id)+'" aria-label="Select '+types[b.type].name+' block '+(i+1)+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+icon(types[b.type].icon)+types[b.type].name+'</button><div><button data-move="'+escape(b.id)+'" data-dir="-1" aria-label="Move '+types[b.type].name+' block '+(i+1)+' up" '+(i===0?'disabled':'')+'>↑</button><button data-move="'+escape(b.id)+'" data-dir="1" aria-label="Move '+types[b.type].name+' block '+(i+1)+' down" '+(i===model.blocks.length-1?'disabled':'')+'>↓</button></div></div>').join('');document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>select(b.dataset.select));document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=model.blocks.findIndex(n=>n.id===b.dataset.move),j=i+Number(b.dataset.dir);if(j<0||j>=model.blocks.length)return;checkpoint();[model.blocks[i],model.blocks[j]]=[model.blocks[j],model.blocks[i]];render();touch();announce('Block moved. The page order has updated.');document.querySelector('[data-select="'+b.dataset.move+'"]').focus()});document.querySelectorAll('[data-add]').forEach(b=>b.disabled=model.blocks.length>=8)}
function renderInspector(){const b=model.blocks.find(n=>n.id===selected),ins=document.querySelector('#builder-inspector');if(!b){ins.innerHTML='<h4>Select a block</h4><p>Add a section, then edit its content here.</p>';return}ins.innerHTML='<span class="kicker">EDIT YOUR CONTENT</span><h4>'+types[b.type].name+' block</h4><label for="builder-title">'+(b.type==='quote'?'Quote':'Heading')+'</label><textarea id="builder-title" rows="3" maxlength="140">'+escape(b.title)+'</textarea><label for="builder-body">'+(b.type==='highlights'?'Three highlights · separate with |':'Supporting text')+'</label><textarea id="builder-body" rows="3" maxlength="500">'+escape(b.body)+'</textarea>'+(b.type!=='highlights'?'<label for="builder-button">'+(b.type==='quote'?'Attribution':'Button label')+'</label><input id="builder-button" maxlength="60" value="'+escape(b.button)+'">':'')+(b.type==='hero'?'<label for="builder-layout">Approved layout</label><select id="builder-layout"><option value="split" '+(model.layout==='split'?'selected':'')+'>Text + visual</option><option value="center" '+(model.layout==='center'?'selected':'')+'>Centered statement</option></select>':'')+'<div class="builder-block-actions"><button id="builder-duplicate">'+icon('layers')+' Duplicate</button><button id="builder-delete">Remove block</button></div><p class="builder-tip">Your content changes. The component handles the layout.</p>';
[['title','builder-title'],['body','builder-body'],['button','builder-button']].forEach(([key,id])=>{const input=document.getElementById(id);if(!input)return;input.onfocus=()=>checkpoint();input.oninput=()=>{b[key]=input.value;renderCanvas();touch()}});const layout=document.querySelector('#builder-layout');if(layout)layout.onchange=()=>{checkpoint();model.layout=layout.value;renderCanvas();touch();announce('Layout updated. Try the mobile preview too.')};document.querySelector('#builder-delete').onclick=()=>{checkpoint();const i=model.blocks.findIndex(n=>n.id===selected);model.blocks.splice(i,1);selected=model.blocks[Math.min(i,model.blocks.length-1)]?.id;render();touch();announce('Block removed. Undo can bring it back.')};document.querySelector('#builder-duplicate').disabled=model.blocks.length>=8;document.querySelector('#builder-duplicate').onclick=()=>{if(model.blocks.length>=8)return;checkpoint();const newBlock={...b,id:'b'+seq++};model.blocks.splice(model.blocks.indexOf(b)+1,0,newBlock);selected=newBlock.id;render();touch();announce('Block duplicated. Edit the new copy.')}}
function render(){renderList();renderInspector();renderCanvas();document.querySelectorAll('[data-builder-theme]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.builderTheme===model.theme));document.querySelectorAll('[data-device]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.device===device));document.querySelector('#builder-undo').disabled=!history.length}
function init(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(model.blocks.length>=8)return;checkpoint();const t=types[b.dataset.add],block={id:'b'+seq++,type:b.dataset.add,title:t.title,body:t.body,button:t.button||''};model.blocks.push(block);selected=block.id;render();touch();announce(t.name+' block added. Edit its content, or move it in Your page.');document.querySelector('#builder-title').focus()});document.querySelectorAll('[data-builder-theme]').forEach(b=>b.onclick=()=>{checkpoint();model.theme=b.dataset.builderTheme;render();touch();announce(themes[model.theme].name+' palette applied to your page.')});document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{device=b.dataset.device;renderCanvas();document.querySelectorAll('[data-device]').forEach(n=>n.setAttribute('aria-pressed',n===b));announce(device==='mobile'?'Mobile preview: the components adapt automatically.':'Desktop preview selected.')});document.querySelector('#builder-undo').onclick=()=>{if(!history.length)return;const previous=history.pop();model=previous.model;selected=previous.selected;if(!model.blocks.some(b=>b.id===selected))selected=model.blocks[0]?.id;render();touch();announce('Previous change restored.')};document.querySelector('#builder-reset').onclick=()=>{checkpoint();model={theme:'coral',layout:'split',blocks:[{id:'b'+seq++,type:'hero',title:types.hero.title,body:types.hero.body,button:types.hero.button},{id:'b'+seq++,type:'highlights',title:types.highlights.title,body:types.highlights.body,button:''}]};selected=model.blocks[0].id;render();touch();announce('Example restored. Your previous draft can be recovered with Undo.')};document.querySelector('#builder-publish').onclick=()=>{if(!model.blocks.length){announce('Add at least one block before publishing.');document.querySelector('[data-add="hero"]').focus();return}const invalid=model.blocks.find(b=>!b.title.trim());if(invalid){select(invalid.id);announce('Add a heading to this block before publishing.');document.querySelector('#builder-title').focus();return}published=clone(model);version++;dirty=false;document.querySelector('#builder-published').innerHTML='<style>'+styles()+'</style>'+pageHTML();document.querySelector('#builder-dialog-description').textContent='Preview version '+version+' · '+model.blocks.length+' blocks · '+themes[model.theme].name+' palette. This snapshot keeps your current draft.';document.querySelector('#builder-state').textContent='Preview published';document.querySelector('#builder-state').classList.add('is-published');document.querySelector('#builder-dialog').showModal();announce('Preview published. Open the page, or download it as a standalone file.')};const dialog=document.querySelector('#builder-dialog');document.querySelector('#builder-close').onclick=()=>dialog.close();document.querySelector('#builder-export').onclick=()=>{if(!published)return;const draft=model;model=published;const output='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>'+escape(published.blocks[0]?.title||'Out Leadership page concept')+'</title><style>body{margin:0;background:#f8f9fc}.page-preview{max-width:1000px;margin:auto}'+styles()+'</style></head><body>'+pageHTML(false)+'</body></html>';model=draft;const blob=new Blob([output],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='out-leadership-page-concept.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();if(!dirty&&published){document.querySelector('#builder-state').textContent='Preview published';document.querySelector('#builder-state').classList.add('is-published')}save()}
return {markup,init};
})();
